import { Agent, computerTool } from "@openai/agents";
import {
  createRetainedAgentRunner,
  RetainedResponseNotAdmitted,
} from "@katalon-experiments/ai-client/agents";
import { requestProvider, providerRetryPolicy } from "./provider.mjs";

function readSteps(body, receiveResults) {
  const messages = Array.isArray(body?.output)
    ? body.output.filter((item) => item?.type === "message")
    : [];
  const text = messages.map((message) =>
    Array.isArray(message.content)
      ? message.content.flatMap((part) =>
          part?.type === "output_text" && typeof part.text === "string"
            ? [part.text]
            : [],
        )
      : [],
  );
  const parse = (value) => {
    try {
      const { steps, test_results } = JSON.parse(value);
      return {
        steps: Array.isArray(steps)
          ? steps.filter((step) => typeof step === "string" && step.trim())
          : [],
        results: Array.isArray(test_results) ? test_results : [],
      };
    } catch {
      return { steps: [], results: [] };
    }
  };
  // Transport boundaries need not match document boundaries. Read complete
  // objects in order from the joined stream, respecting braces inside strings.
  const joined = text.flat().join("");
  const documents = [];
  const add = (value, start, end) => {
    const { steps, results } = parse(value);
    if (steps.length || results.length)
      documents.push({ start, end, steps, results });
  };
  let start = -1;
  let depth = 0;
  let quoted = false;
  let escaped = false;
  for (let i = 0; i < joined.length; i++) {
    const character = joined[i];
    if (start < 0) {
      if (character === "{") {
        start = i;
        depth = 1;
      }
      continue;
    }
    if (quoted) {
      if (escaped) escaped = false;
      else if (character === "\\") escaped = true;
      else if (character === '"') quoted = false;
    } else if (character === '"') quoted = true;
    else if (character === "{") depth++;
    else if (character === "}" && --depth === 0) {
      add(joined.slice(start, i + 1), start, i + 1);
      start = -1;
    }
  }
  // An unfinished neighboring document must not swallow a complete message or
  // text part. Source ranges keep overlapping representations from duplicating
  // observations that the joined stream already recovered.
  let offset = 0;
  for (const parts of text) {
    const message = parts.join("");
    add(message, offset, offset + message.length);
    for (const part of parts) {
      add(part, offset, offset + part.length);
      offset += part.length;
    }
  }
  documents.sort((a, b) => a.start - b.start || b.end - a.end);
  const steps = [];
  const results = [];
  let end = -1;
  for (const document of documents) {
    if (document.start < end) continue;
    steps.push(...document.steps);
    results.push(...document.results);
    end = document.end;
  }
  receiveResults?.(results);
  return steps.length ? steps : null;
}

export async function requestBrowserRecap(options) {
  const { request, signal } = options;
  const closed = () => {
    throw new Error("Recap cannot perform actions");
  };
  const agent = new Agent({
    name: "Runner",
    tools: request.tools.map(() =>
      computerTool({
        computer: {
          screenshot: closed,
          click: closed,
          doubleClick: closed,
          drag: closed,
          keypress: closed,
          move: closed,
          scroll: closed,
          type: closed,
          wait: closed,
        },
      }),
    ),
    modelSettings: {
      reasoning: request.reasoning,
      maxTokens: request.max_output_tokens,
      ...(request.tool_choice ? { toolChoice: request.tool_choice } : {}),
    },
    outputType: request.text.format,
  });
  let steps,
    testResults = [];
  const runner = createRetainedAgentRunner({
    model: request.model,
    store: request.store,
    async dispatch() {
      // The host sends the original bytes and records the original reply.
      const { body } = await requestProvider(options);
      if (!signal?.aborted)
        steps = readSteps(body, (results) => {
          testResults = results;
        });
      if (!steps && !testResults.length)
        throw new RetainedResponseNotAdmitted("Invalid browser recap");
      return {
        ...body,
        output: [
          {
            type: "message",
            role: "assistant",
            status: "completed",
            content: [
              {
                type: "output_text",
                text: JSON.stringify({
                  steps: steps ?? [],
                  ...(request.text.format.schema.properties.test_results
                    ? { test_results: testResults }
                    : {}),
                }),
              },
            ],
          },
        ],
      };
    },
  });
  try {
    await runner.run(
      agent,
      request.input.map((item) => ({
        type: "unknown",
        providerData: item,
      })),
      { previousResponseId: request.previous_response_id, maxTurns: 1 },
    );
  } catch (error) {
    // SDK metadata/status admission does not erase text already received.
    // No tool call from the recap is executed, and the raw response stays retained.
    if (
      !steps &&
      !testResults.length &&
      !(error instanceof RetainedResponseNotAdmitted)
    )
      throw error;
  }
  if (!signal?.aborted) options.onTestResults?.(testResults);
  return signal?.aborted ? null : (steps ?? null);
}

export async function collectExecutionRecap({
  request,
  api,
  apiKey,
  requestAI,
  signal,
  headersFor,
  record,
  save,
  redact,
  executionElapsedMs,
  onError,
}) {
  try {
    await save("recap-request.json", request);
    let testResults = [];
    const steps = await requestBrowserRecap({
      onTestResults: (results) => {
        testResults = results;
      },
      api,
      apiKey,
      requestAI,
      request,
      signal,
      deadline: Date.now() + providerRetryPolicy.requestTimeoutMs,
      remainingAttempts: 1,
      headersFor,
      record: async (receipt) => {
        await record(receipt);
        await save("recap-transport.json", receipt.row);
        if (receipt.bodyText !== undefined)
          await save("recap-response.json", receipt.bodyText);
      },
    });
    if ((!steps && !testResults.length) || signal?.aborted) return null;
    return {
      schema: "loki.runner.execution-recap/1",
      steps: (steps ?? []).map((step) => redact.text(step.trim())),
      ...(testResults.length
        ? { testResults: JSON.parse(redact.text(JSON.stringify(testResults))) }
        : {}),
      executionElapsedMs,
    };
  } catch (error) {
    await onError?.(error);
    return null;
  }
}

export function recapContinuation({
  disposition,
  report,
  history,
  activityCount,
  stoppedAtLimit,
}) {
  const recapDisposition =
    report &&
    ((disposition.state === "completed" && report.status === "complete") ||
      (disposition.state === "incomplete" &&
        disposition.terminal?.actor === "model" &&
        report.responseId === disposition.terminal.responseId &&
        report.callId === disposition.terminal.callId));
  const { unexecutedTurn, completedModelFinal, settledContinuation } = history;
  const providerFailureWithObservations =
    disposition.state === "incomplete" &&
    ["API", "transport"].includes(disposition.terminal?.actor) &&
    unexecutedTurn?.activityCount === activityCount;
  const unansweredQuestionAtLimit =
    stoppedAtLimit &&
    disposition.terminal.reason === "Time limit" &&
    report?.status === "needs_input";
  return completedModelFinal
    ? { ...completedModelFinal, stopReason: disposition.terminal.reason }
    : recapDisposition
      ? {
          ...report,
          ...(settledContinuation?.responseId === report.responseId
            ? { continuation: settledContinuation.continuation }
            : {}),
        }
      : unansweredQuestionAtLimit
        ? {
            ...report,
            stopReason: "Time limit; the clarification was not answered",
            continuation: [
              {
                type: "function_call_output",
                call_id: report.callId,
                output: JSON.stringify({
                  status: "not_answered",
                  reason: "Time limit",
                }),
              },
            ],
          }
        : providerFailureWithObservations
          ? { ...unexecutedTurn, stopReason: disposition.terminal.reason }
          : stoppedAtLimit &&
              settledContinuation?.activityCount === activityCount
            ? {
                ...settledContinuation,
                stopReason: disposition.terminal.reason,
              }
            : null;
}
